package bcx.tr;

import bcx.tr.Cls.Mth;
import org.objectweb.asm.Handle;
import org.objectweb.asm.Opcodes;
import org.objectweb.asm.Type;
import org.objectweb.asm.tree.*;

import java.util.*;

/**
 * Replaces each invokedynamic by an invokestatic of generated bytecode doing what the JDK's bootstrap links:
 * lambdas (LambdaMetafactory), string concatenation (StringConcatFactory), records (ObjectMethods) and pattern
 * switches (SwitchBootstraps). The generated code is uninstrumented, as the JDK's spun classes are; the indy itself
 * costs nothing in instrumented code, and the replacement adds no counting.
 */
final class Indy implements Opcodes {
    final Pool pool;
    private final Map<String, Integer> counters = new HashMap<>();

    Indy(Pool pool) { this.pool = pool; }

    void rewrite(Rta rta, Mth m) {
        boolean any = false;
        for (AbstractInsnNode in : m.node.instructions) if (in instanceof InvokeDynamicInsnNode) { any = true; break; }
        if (!any) return;
        for (AbstractInsnNode in : m.node.instructions.toArray()) {
            if (!(in instanceof InvokeDynamicInsnNode id)) continue;
            MethodInsnNode repl = link(m.owner, id);
            m.node.instructions.set(id, repl);
        }
    }

    private int next(Cls c, String kind) { return counters.merge(c.mod.id + ":" + c.name + kind, 1, Integer::sum); }

    private MethodInsnNode link(Cls caller, InvokeDynamicInsnNode id) {
        String bsm = id.bsm.getOwner() + "." + id.bsm.getName();
        switch (bsm) {
            case "java/lang/invoke/LambdaMetafactory.metafactory":
            case "java/lang/invoke/LambdaMetafactory.altMetafactory":
                return lambda(caller, id, bsm.endsWith("altMetafactory"));
            case "java/lang/invoke/StringConcatFactory.makeConcatWithConstants":
                return helper(caller, id, concat(id));
            case "java/lang/runtime/ObjectMethods.bootstrap":
                return helper(caller, id, record(caller, id));
            case "java/lang/runtime/SwitchBootstraps.typeSwitch":
                return helper(caller, id, typeSwitch(caller, id));
            default:
                throw new TranslateException("unsupported invokedynamic bootstrap " + bsm + " in " + caller);
        }
    }

    /** A static helper method, in a synthetic class of the caller's module, with the indy's descriptor. */
    private MethodInsnNode helper(Cls caller, InvokeDynamicInsnNode id, InsnList body) {
        int k = next(caller, "$$Indy");
        String cname = caller.name + "$$Indy" + k;
        ClassNode cn = synth(cname, "java/lang/Object", new String[0]);
        MethodNode mn = new MethodNode(ACC_PUBLIC | ACC_STATIC, "call", id.desc, null, null);
        mn.instructions = body;
        mn.maxStack = 16;
        mn.maxLocals = Type.getArgumentsAndReturnSizes(id.desc) >> 2;
        mn.maxLocals += 8;
        cn.methods.add(mn);
        pool.addSynthetic(caller.mod, cn);
        return new MethodInsnNode(INVOKESTATIC, cname, "call", id.desc, false);
    }

    private static ClassNode synth(String name, String sup, String[] ifaces) {
        ClassNode cn = new ClassNode();
        cn.version = V21;
        cn.access = ACC_PUBLIC | ACC_FINAL | ACC_SYNTHETIC;
        cn.name = name;
        cn.superName = sup;
        cn.interfaces = new ArrayList<>(Arrays.asList(ifaces));
        return cn;
    }

    // ---------------- string concatenation
    private InsnList concat(InvokeDynamicInsnNode id) {
        String recipe = (String) id.bsmArgs[0];
        int ci = 1;
        Type[] args = Type.getArgumentTypes(id.desc);
        InsnList l = new InsnList();
        l.add(new TypeInsnNode(NEW, "java/lang/StringBuilder"));
        l.add(new InsnNode(DUP));
        l.add(new MethodInsnNode(INVOKESPECIAL, "java/lang/StringBuilder", "<init>", "()V", false));
        int ai = 0, slot = 0;
        StringBuilder lit = new StringBuilder();
        for (int i = 0; i < recipe.length(); i++) {
            char c = recipe.charAt(i);
            if (c == '\u0001' || c == '\u0002') {
                if (lit.length() > 0) { appendConst(l, lit.toString()); lit.setLength(0); }
                if (c == '\u0002') {
                    Object cst = id.bsmArgs[ci++];
                    appendConst(l, String.valueOf(cst));
                } else {
                    Type t = args[ai++];
                    l.add(new VarInsnNode(t.getOpcode(ILOAD), slot));
                    slot += t.getSize();
                    String d = switch (t.getSort()) {
                        case Type.INT, Type.BYTE, Type.SHORT -> "(I)";
                        case Type.CHAR -> "(C)";
                        case Type.BOOLEAN -> "(Z)";
                        case Type.LONG -> "(J)";
                        case Type.FLOAT -> "(F)";
                        case Type.DOUBLE -> "(D)";
                        default -> t.getDescriptor().equals("Ljava/lang/String;") ? "(Ljava/lang/String;)" : "(Ljava/lang/Object;)";
                    };
                    l.add(new MethodInsnNode(INVOKEVIRTUAL, "java/lang/StringBuilder", "append", d + "Ljava/lang/StringBuilder;", false));
                }
            } else lit.append(c);
        }
        if (lit.length() > 0) appendConst(l, lit.toString());
        l.add(new MethodInsnNode(INVOKEVIRTUAL, "java/lang/StringBuilder", "toString", "()Ljava/lang/String;", false));
        l.add(new InsnNode(ARETURN));
        return l;
    }

    private static void appendConst(InsnList l, String s) {
        l.add(new LdcInsnNode(s));
        l.add(new MethodInsnNode(INVOKEVIRTUAL, "java/lang/StringBuilder", "append", "(Ljava/lang/String;)Ljava/lang/StringBuilder;", false));
    }

    // ---------------- lambdas
    private MethodInsnNode lambda(Cls caller, InvokeDynamicInsnNode id, boolean alt) {
        Type samType = (Type) id.bsmArgs[0];
        Handle impl = (Handle) id.bsmArgs[1];
        Type instType = (Type) id.bsmArgs[2];
        String itf = Type.getReturnType(id.desc).getInternalName();
        List<String> ifaces = new ArrayList<>(List.of(itf));
        List<Type> bridges = new ArrayList<>();
        if (alt) {
            int flags = (Integer) id.bsmArgs[3];
            int ai = 4;
            if ((flags & 1) != 0 && !ifaces.contains("java/io/Serializable")) ifaces.add("java/io/Serializable"); // FLAG_SERIALIZABLE
            if ((flags & 2) != 0) { // FLAG_MARKERS
                int n = (Integer) id.bsmArgs[ai++];
                for (int i = 0; i < n; i++) ifaces.add(((Type) id.bsmArgs[ai++]).getInternalName());
            }
            if ((flags & 4) != 0) { // FLAG_BRIDGES
                int n = (Integer) id.bsmArgs[ai++];
                for (int i = 0; i < n; i++) bridges.add((Type) id.bsmArgs[ai++]);
            }
        }
        int k = next(caller, "$$Lambda");
        String name = caller.name + "$$Lambda$" + k;
        ClassNode cn = synth(name, "java/lang/Object", ifaces.toArray(new String[0]));
        Type[] caps = Type.getArgumentTypes(id.desc);
        for (int i = 0; i < caps.length; i++)
            cn.fields.add(new FieldNode(ACC_PRIVATE | ACC_FINAL, "arg$" + (i + 1), caps[i].getDescriptor(), null, null));
        // constructor
        String ctorDesc = Type.getMethodDescriptor(Type.VOID_TYPE, caps);
        MethodNode ctor = new MethodNode(ACC_PRIVATE, "<init>", ctorDesc, null, null);
        InsnList c = ctor.instructions;
        c.add(new VarInsnNode(ALOAD, 0));
        c.add(new MethodInsnNode(INVOKESPECIAL, "java/lang/Object", "<init>", "()V", false));
        int slot = 1;
        for (int i = 0; i < caps.length; i++) {
            c.add(new VarInsnNode(ALOAD, 0));
            c.add(new VarInsnNode(caps[i].getOpcode(ILOAD), slot));
            slot += caps[i].getSize();
            c.add(new FieldInsnNode(PUTFIELD, name, "arg$" + (i + 1), caps[i].getDescriptor()));
        }
        c.add(new InsnNode(RETURN));
        ctor.maxStack = 4; ctor.maxLocals = slot;
        cn.methods.add(ctor);
        // factory: a fresh instance per evaluation if capturing, else one instance per linkage
        String factDesc = id.desc;
        MethodNode fact = new MethodNode(ACC_PUBLIC | ACC_STATIC, "make", factDesc, null, null);
        InsnList f = fact.instructions;
        if (caps.length == 0) {
            cn.fields.add(new FieldNode(ACC_PRIVATE | ACC_STATIC | ACC_FINAL, "INSTANCE", "L" + name + ";", null, null));
            MethodNode cl = new MethodNode(ACC_STATIC, "<clinit>", "()V", null, null);
            cl.instructions.add(new TypeInsnNode(NEW, name));
            cl.instructions.add(new InsnNode(DUP));
            cl.instructions.add(new MethodInsnNode(INVOKESPECIAL, name, "<init>", "()V", false));
            cl.instructions.add(new FieldInsnNode(PUTSTATIC, name, "INSTANCE", "L" + name + ";"));
            cl.instructions.add(new InsnNode(RETURN));
            cl.maxStack = 2; cl.maxLocals = 0;
            cn.methods.add(cl);
            f.add(new FieldInsnNode(GETSTATIC, name, "INSTANCE", "L" + name + ";"));
        } else {
            f.add(new TypeInsnNode(NEW, name));
            f.add(new InsnNode(DUP));
            slot = 0;
            for (Type t : caps) { f.add(new VarInsnNode(t.getOpcode(ILOAD), slot)); slot += t.getSize(); }
            f.add(new MethodInsnNode(INVOKESPECIAL, name, "<init>", ctorDesc, false));
        }
        f.add(new InsnNode(ARETURN));
        fact.maxStack = 2 + slot + 2; fact.maxLocals = slot;
        cn.methods.add(fact);
        // the interface method and its bridges
        LinkedHashSet<String> descs = new LinkedHashSet<>();
        descs.add(samType.getDescriptor());
        for (Type b : bridges) descs.add(b.getDescriptor());
        for (String d : descs) cn.methods.add(samMethod(name, id.name, d, caps, impl, instType));
        pool.addSynthetic(caller.mod, cn);
        return new MethodInsnNode(INVOKESTATIC, name, "make", factDesc, false);
    }

    private MethodNode samMethod(String cls, String mname, String desc, Type[] caps, Handle impl, Type instType) {
        MethodNode mn = new MethodNode(ACC_PUBLIC, mname, desc, null, null);
        InsnList l = mn.instructions;
        Type[] samArgs = Type.getArgumentTypes(desc);
        Type[] instArgs = instType.getArgumentTypes();
        Type implMT = Type.getMethodType(impl.getDesc());
        int tag = impl.getTag();
        List<Type> implParams = new ArrayList<>();
        if (tag == H_INVOKEVIRTUAL || tag == H_INVOKEINTERFACE || tag == H_INVOKESPECIAL)
            implParams.add(Type.getObjectType(impl.getOwner()));
        implParams.addAll(Arrays.asList(implMT.getArgumentTypes()));
        if (tag == H_NEWINVOKESPECIAL) {
            l.add(new TypeInsnNode(NEW, impl.getOwner()));
            l.add(new InsnNode(DUP));
        }
        int p = 0;
        for (int i = 0; i < caps.length; i++, p++) {
            l.add(new VarInsnNode(ALOAD, 0));
            l.add(new FieldInsnNode(GETFIELD, cls, "arg$" + (i + 1), caps[i].getDescriptor()));
            convert(l, caps[i], implParams.get(p));
        }
        int slot = 1;
        for (int i = 0; i < samArgs.length; i++, p++) {
            l.add(new VarInsnNode(samArgs[i].getOpcode(ILOAD), slot));
            slot += samArgs[i].getSize();
            Type dyn = i < instArgs.length ? instArgs[i] : samArgs[i];
            if (samArgs[i].getSort() >= Type.ARRAY && dyn.getSort() >= Type.ARRAY && !dyn.equals(samArgs[i]))
                l.add(new TypeInsnNode(CHECKCAST, dyn.getInternalName()));
            convert(l, dyn, implParams.get(p));
        }
        switch (tag) {
            case H_INVOKESTATIC -> l.add(new MethodInsnNode(INVOKESTATIC, impl.getOwner(), impl.getName(), impl.getDesc(), impl.isInterface()));
            case H_INVOKEVIRTUAL -> l.add(new MethodInsnNode(INVOKEVIRTUAL, impl.getOwner(), impl.getName(), impl.getDesc(), false));
            case H_INVOKEINTERFACE -> l.add(new MethodInsnNode(INVOKEINTERFACE, impl.getOwner(), impl.getName(), impl.getDesc(), true));
            case H_INVOKESPECIAL -> l.add(new MethodInsnNode(INVOKESPECIAL, impl.getOwner(), impl.getName(), impl.getDesc(), impl.isInterface()));
            case H_NEWINVOKESPECIAL -> l.add(new MethodInsnNode(INVOKESPECIAL, impl.getOwner(), "<init>", impl.getDesc(), false));
            default -> throw new TranslateException("lambda impl handle kind " + tag);
        }
        Type implRet = tag == H_NEWINVOKESPECIAL ? Type.getObjectType(impl.getOwner()) : implMT.getReturnType();
        Type samRet = Type.getReturnType(desc);
        if (samRet.getSort() == Type.VOID) {
            if (implRet.getSort() != Type.VOID) l.add(new InsnNode(implRet.getSize() == 2 ? POP2 : POP));
            l.add(new InsnNode(RETURN));
        } else {
            convert(l, implRet, samRet);
            l.add(new InsnNode(samRet.getOpcode(IRETURN)));
        }
        mn.maxStack = 4 + 2 * (caps.length + samArgs.length + 2);
        mn.maxLocals = slot;
        return mn;
    }

    /** LambdaMetafactory's argument/return adaptation (boxing, unboxing, widening, casts). */
    static void convert(InsnList l, Type from, Type to) {
        if (from.equals(to)) return;
        boolean fp = from.getSort() < Type.ARRAY, tp = to.getSort() < Type.ARRAY;
        if (fp && tp) { widen(l, from, to); return; }
        if (fp) { // box
            Type w = wrapper(from);
            l.add(new MethodInsnNode(INVOKESTATIC, w.getInternalName(), "valueOf", "(" + from.getDescriptor() + ")" + w.getDescriptor(), false));
            if (!to.getInternalName().equals(w.getInternalName()) && !to.getInternalName().equals("java/lang/Object"))
                l.add(new TypeInsnNode(CHECKCAST, to.getInternalName()));
            return;
        }
        if (tp) { // unbox: from a wrapper (or Object/Number: cast to the target's wrapper)
            Type w = wrapper(to);
            String fn = from.getInternalName();
            Type src = isWrapper(fn) ? Type.getObjectType(fn) : w;
            if (!fn.equals(src.getInternalName())) l.add(new TypeInsnNode(CHECKCAST, src.getInternalName()));
            Type prim = primOf(src.getInternalName());
            l.add(new MethodInsnNode(INVOKEVIRTUAL, src.getInternalName(), prim.getClassName() + "Value", "()" + prim.getDescriptor(), false));
            widen(l, prim, to);
            return;
        }
        if (!to.getDescriptor().equals("Ljava/lang/Object;"))
            l.add(new TypeInsnNode(CHECKCAST, to.getSort() == Type.ARRAY ? to.getDescriptor() : to.getInternalName()));
    }

    private static void widen(InsnList l, Type from, Type to) {
        int f = from.getSort(), t = to.getSort();
        if (f == t) return;
        boolean fi = f == Type.INT || f == Type.BYTE || f == Type.SHORT || f == Type.CHAR || f == Type.BOOLEAN;
        if (fi && (t == Type.INT || t == Type.SHORT || t == Type.CHAR || t == Type.BYTE)) return;
        if (fi) { l.add(new InsnNode(t == Type.LONG ? I2L : t == Type.FLOAT ? I2F : I2D)); return; }
        if (f == Type.LONG) { l.add(new InsnNode(t == Type.FLOAT ? L2F : L2D)); return; }
        if (f == Type.FLOAT && t == Type.DOUBLE) { l.add(new InsnNode(F2D)); return; }
        throw new TranslateException("lambda conversion " + from + " -> " + to);
    }

    static boolean isWrapper(String n) {
        return switch (n) {
            case "java/lang/Integer", "java/lang/Long", "java/lang/Float", "java/lang/Double", "java/lang/Short",
                 "java/lang/Byte", "java/lang/Character", "java/lang/Boolean" -> true;
            default -> false;
        };
    }

    static Type primOf(String w) {
        return switch (w) {
            case "java/lang/Integer" -> Type.INT_TYPE;
            case "java/lang/Long" -> Type.LONG_TYPE;
            case "java/lang/Float" -> Type.FLOAT_TYPE;
            case "java/lang/Double" -> Type.DOUBLE_TYPE;
            case "java/lang/Short" -> Type.SHORT_TYPE;
            case "java/lang/Byte" -> Type.BYTE_TYPE;
            case "java/lang/Character" -> Type.CHAR_TYPE;
            case "java/lang/Boolean" -> Type.BOOLEAN_TYPE;
            default -> throw new TranslateException("not a wrapper " + w);
        };
    }

    static Type wrapper(Type p) {
        return Type.getObjectType(switch (p.getSort()) {
            case Type.INT -> "java/lang/Integer";
            case Type.LONG -> "java/lang/Long";
            case Type.FLOAT -> "java/lang/Float";
            case Type.DOUBLE -> "java/lang/Double";
            case Type.SHORT -> "java/lang/Short";
            case Type.BYTE -> "java/lang/Byte";
            case Type.CHAR -> "java/lang/Character";
            case Type.BOOLEAN -> "java/lang/Boolean";
            default -> throw new TranslateException("no wrapper for " + p);
        });
    }

    // ---------------- records (java.lang.runtime.ObjectMethods, JDK 21)
    private InsnList record(Cls caller, InvokeDynamicInsnNode id) {
        Type rec = (Type) id.bsmArgs[0];
        String names = (String) id.bsmArgs[1];
        List<Handle> getters = new ArrayList<>();
        for (int i = 2; i < id.bsmArgs.length; i++) getters.add((Handle) id.bsmArgs[i]);
        String rn = rec.getInternalName();
        InsnList l = new InsnList();
        switch (id.name) {
            case "hashCode" -> {
                l.add(new InsnNode(ICONST_0));
                for (Handle g : getters) {
                    // acc * 31 + hash(field)
                    l.add(new IntInsnNode(BIPUSH, 31));
                    l.add(new InsnNode(IMUL));
                    l.add(new VarInsnNode(ALOAD, 0));
                    l.add(new FieldInsnNode(GETFIELD, g.getOwner(), g.getName(), g.getDesc()));
                    hasher(l, Type.getType(g.getDesc()));
                    l.add(new InsnNode(IADD));
                }
                l.add(new InsnNode(IRETURN));
            }
            case "equals" -> {
                LabelNode yes = new LabelNode(), no = new LabelNode();
                l.add(new VarInsnNode(ALOAD, 0));
                l.add(new VarInsnNode(ALOAD, 1));
                l.add(new JumpInsnNode(IF_ACMPEQ, yes));
                l.add(new VarInsnNode(ALOAD, 1));
                l.add(new TypeInsnNode(INSTANCEOF, rn));
                l.add(new JumpInsnNode(IFEQ, no));
                // fields compared last to first, as the JDK's nested guardWithTest does
                for (int i = getters.size() - 1; i >= 0; i--) {
                    Handle g = getters.get(i);
                    Type t = Type.getType(g.getDesc());
                    l.add(new VarInsnNode(ALOAD, 0));
                    l.add(new FieldInsnNode(GETFIELD, g.getOwner(), g.getName(), g.getDesc()));
                    l.add(new VarInsnNode(ALOAD, 1));
                    l.add(new TypeInsnNode(CHECKCAST, rn));
                    l.add(new FieldInsnNode(GETFIELD, g.getOwner(), g.getName(), g.getDesc()));
                    switch (t.getSort()) {
                        case Type.FLOAT -> { l.add(new MethodInsnNode(INVOKESTATIC, "java/lang/Float", "compare", "(FF)I", false)); l.add(new JumpInsnNode(IFNE, no)); }
                        case Type.DOUBLE -> { l.add(new MethodInsnNode(INVOKESTATIC, "java/lang/Double", "compare", "(DD)I", false)); l.add(new JumpInsnNode(IFNE, no)); }
                        case Type.LONG -> { l.add(new InsnNode(LCMP)); l.add(new JumpInsnNode(IFNE, no)); }
                        case Type.OBJECT, Type.ARRAY -> {
                            l.add(new MethodInsnNode(INVOKESTATIC, "java/util/Objects", "equals", "(Ljava/lang/Object;Ljava/lang/Object;)Z", false));
                            l.add(new JumpInsnNode(IFEQ, no));
                        }
                        default -> l.add(new JumpInsnNode(IF_ICMPNE, no));
                    }
                }
                l.add(yes);
                l.add(new InsnNode(ICONST_1));
                l.add(new InsnNode(IRETURN));
                l.add(no);
                l.add(new InsnNode(ICONST_0));
                l.add(new InsnNode(IRETURN));
            }
            case "toString" -> {
                String simple = rn.substring(rn.lastIndexOf('/') + 1);
                simple = simple.substring(simple.lastIndexOf('$') + 1);
                String[] ns = names.isEmpty() ? new String[0] : names.split(";");
                l.add(new TypeInsnNode(NEW, "java/lang/StringBuilder"));
                l.add(new InsnNode(DUP));
                l.add(new MethodInsnNode(INVOKESPECIAL, "java/lang/StringBuilder", "<init>", "()V", false));
                appendConst(l, simple + "[");
                for (int i = 0; i < getters.size(); i++) {
                    Handle g = getters.get(i);
                    appendConst(l, (i > 0 ? ", " : "") + ns[i] + "=");
                    l.add(new VarInsnNode(ALOAD, 0));
                    l.add(new FieldInsnNode(GETFIELD, g.getOwner(), g.getName(), g.getDesc()));
                    Type t = Type.getType(g.getDesc());
                    String d = switch (t.getSort()) {
                        case Type.INT, Type.BYTE, Type.SHORT -> "(I)";
                        case Type.CHAR -> "(C)";
                        case Type.BOOLEAN -> "(Z)";
                        case Type.LONG -> "(J)";
                        case Type.FLOAT -> "(F)";
                        case Type.DOUBLE -> "(D)";
                        default -> "(Ljava/lang/Object;)";
                    };
                    l.add(new MethodInsnNode(INVOKEVIRTUAL, "java/lang/StringBuilder", "append", d + "Ljava/lang/StringBuilder;", false));
                }
                appendConst(l, "]");
                l.add(new MethodInsnNode(INVOKEVIRTUAL, "java/lang/StringBuilder", "toString", "()Ljava/lang/String;", false));
                l.add(new InsnNode(ARETURN));
            }
            default -> throw new TranslateException("record method " + id.name);
        }
        return l;
    }

    private static void hasher(InsnList l, Type t) {
        String w = switch (t.getSort()) {
            case Type.INT -> "java/lang/Integer";
            case Type.LONG -> "java/lang/Long";
            case Type.FLOAT -> "java/lang/Float";
            case Type.DOUBLE -> "java/lang/Double";
            case Type.SHORT -> "java/lang/Short";
            case Type.BYTE -> "java/lang/Byte";
            case Type.CHAR -> "java/lang/Character";
            case Type.BOOLEAN -> "java/lang/Boolean";
            default -> null;
        };
        if (w != null) l.add(new MethodInsnNode(INVOKESTATIC, w, "hashCode", "(" + t.getDescriptor() + ")I", false));
        else l.add(new MethodInsnNode(INVOKESTATIC, "java/util/Objects", "hashCode", "(Ljava/lang/Object;)I", false));
    }

    // ---------------- pattern switch (java.lang.runtime.SwitchBootstraps.typeSwitch, JDK 21)
    private InsnList typeSwitch(Cls caller, InvokeDynamicInsnNode id) {
        InsnList l = new InsnList();
        Object[] labels = id.bsmArgs;
        LabelNode notNull = new LabelNode();
        l.add(new VarInsnNode(ALOAD, 0));
        l.add(new JumpInsnNode(IFNONNULL, notNull));
        l.add(new InsnNode(ICONST_M1));
        l.add(new InsnNode(IRETURN));
        l.add(notNull);
        for (int i = 0; i < labels.length; i++) {
            LabelNode skip = new LabelNode();
            // if (restart > i) skip
            l.add(new VarInsnNode(ILOAD, 1));
            l.add(ldcInt(i));
            l.add(new JumpInsnNode(IF_ICMPGT, skip));
            Object lab = labels[i];
            if (lab instanceof Type t) {
                l.add(new VarInsnNode(ALOAD, 0));
                l.add(new TypeInsnNode(INSTANCEOF, t.getSort() == Type.ARRAY ? t.getDescriptor() : t.getInternalName()));
                l.add(new JumpInsnNode(IFEQ, skip));
            } else if (lab instanceof String s) {
                l.add(new VarInsnNode(ALOAD, 0));
                l.add(new LdcInsnNode(s));
                l.add(new MethodInsnNode(INVOKEVIRTUAL, "java/lang/Object", "equals", "(Ljava/lang/Object;)Z", false));
                l.add(new JumpInsnNode(IFEQ, skip));
            } else if (lab instanceof Integer n) {
                LabelNode chr = new LabelNode(), hit = new LabelNode();
                l.add(new VarInsnNode(ALOAD, 0));
                l.add(new TypeInsnNode(INSTANCEOF, "java/lang/Number"));
                l.add(new JumpInsnNode(IFEQ, chr));
                l.add(new VarInsnNode(ALOAD, 0));
                l.add(new TypeInsnNode(CHECKCAST, "java/lang/Number"));
                l.add(new MethodInsnNode(INVOKEVIRTUAL, "java/lang/Number", "intValue", "()I", false));
                l.add(ldcInt(n));
                l.add(new JumpInsnNode(IF_ICMPEQ, hit));
                l.add(new JumpInsnNode(GOTO, skip));
                l.add(chr);
                l.add(new VarInsnNode(ALOAD, 0));
                l.add(new TypeInsnNode(INSTANCEOF, "java/lang/Character"));
                l.add(new JumpInsnNode(IFEQ, skip));
                l.add(new VarInsnNode(ALOAD, 0));
                l.add(new TypeInsnNode(CHECKCAST, "java/lang/Character"));
                l.add(new MethodInsnNode(INVOKEVIRTUAL, "java/lang/Character", "charValue", "()C", false));
                l.add(ldcInt(n));
                l.add(new JumpInsnNode(IF_ICMPNE, skip));
                l.add(hit);
            } else {
                throw new TranslateException("typeSwitch label " + lab + " in " + caller);
            }
            l.add(ldcInt(i));
            l.add(new InsnNode(IRETURN));
            l.add(skip);
        }
        l.add(ldcInt(labels.length));
        l.add(new InsnNode(IRETURN));
        return l;
    }

    private static AbstractInsnNode ldcInt(int v) { return new LdcInsnNode(v); }
}
